/* Developer verification only. Uses Playwright externally; dashboard needs no runtime. */
const fs=require('fs'),path=require('path'),{pathToFileURL}=require('url'),assert=require('assert');
const {chromium}=require(process.env.PLAYWRIGHT_PATH||'C:/Users/sam/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const root=process.env.TOOLKIT_ROOT||path.resolve(__dirname,'../../NEIGHBOR-CIRCUIT-TOOLKIT'),url=pathToFileURL(path.join(root,'index.html')).href;
const out=process.env.VALIDATION_OUT||path.resolve(__dirname,'../../.development/browser-validation');fs.mkdirSync(out,{recursive:true});
const results=[],errors=[],network=[];
function pass(name){results.push({name,passed:true});console.log('PASS '+name)}
(async()=>{
 const browser=await chromium.launch({executablePath:process.env.BROWSER_EXECUTABLE||'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',headless:true});
 const context=await browser.newContext({viewport:{width:1440,height:1000},acceptDownloads:true});
 await context.setOffline(true);
 const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>{if(/^https?:/.test(r.url()))network.push(r.url())});
 await page.goto(url);await page.waitForSelector('h1');
 assert.equal(await page.title(),'Neighbor Circuit Toolkit');assert((await page.locator('h1').innerText()).includes('Ready'));pass('Direct file:// startup with network offline');
 const dependencyCheck=await page.evaluate(()=>[...document.querySelectorAll('script[src],link[rel=stylesheet],img')].map(e=>({url:e.src||e.href,ok:e.tagName!=='IMG'||e.complete&&e.naturalWidth>0})));
 assert(dependencyCheck.every(x=>x.url.startsWith('file:')&&x.ok));for(const x of dependencyCheck)assert(fs.existsSync(require('url').fileURLToPath(x.url)));pass('All dashboard dependencies are local and present');
 await page.screenshot({path:path.join(out,'overview-dark-1440.png'),fullPage:true});
 for(const [q,id] of [['GPU crash','ddu'],['AI','win11debloat'],['remove OneDrive','win11debloat'],['recover files','dmde'],['no Wi-Fi','sdio'],["PC won't boot",'hirens'],['malware','safetyscanner'],['SSD','cdi']]){
  await page.locator('#search').fill(q);assert(await page.locator(`[data-tool-id="${id}"]`).count(),q+' did not match '+id);
 }pass('Eight symptom searches return the expected tools and workflows');
 await page.locator('#clear-filters').click();await page.locator('[data-kind="Boot ISO"]').click();assert(await page.locator('.tool-card').count()>5);assert(await page.locator('.tool-card .tool-meta').evaluateAll(es=>es.every(e=>e.textContent.includes('Boot ISO'))));pass('Boot filter constrains results');
 await page.locator('#priority').selectOption('P1');assert(await page.locator('.tool-card .badges').evaluateAll(es=>es.every(e=>e.textContent.includes('ESSENTIAL'))));pass('Priority combines with type filter');
 await page.locator('#clear-filters').click();await page.locator('#kind').selectOption('Firmware');assert(await page.locator('.tool-card').count()>5);pass('Firmware type filter');
 await page.locator('#clear-filters').click();await page.locator('#search').fill('CrystalDiskInfo');
 const fav=page.locator('[data-favorite="cdi"]');const old=await fav.getAttribute('aria-pressed');await fav.click();await page.reload();await page.locator('#search').fill('CrystalDiskInfo');assert.notEqual(await page.locator('[data-favorite="cdi"]').getAttribute('aria-pressed'),old);pass('Favorites persist after reload');
 await page.locator('#favorites-filter').click();assert.equal(await page.locator('[data-tool-id="cdi"]').count(),old==='true'?0:1);pass('Favorites filter respects saved state');
 await page.locator('[data-nav="tools"]').first().click();await page.locator('#installed-filter').click();const installed=await page.evaluate(()=>Object.values(window.LOCAL_INVENTORY.tools).filter(t=>t.installed).length);assert.equal(await page.locator('.tool-card').count(),installed);pass('Installed-only filter uses inventory, not browser guesses');
 await page.locator('[data-nav="tools"]').first().click();await page.locator('[data-category="Windows AI Controls"]').click();assert(await page.locator('[data-tool-id="win11debloat"]').count());pass('Sidebar supports cross-category membership');
 for(const m of ['list','compact','cards']){await page.locator(`[data-mode="${m}"]`).click();assert.equal(await page.locator(`[data-mode="${m}"]`).getAttribute('aria-pressed'),'true')}pass('All three display modes operate');
 await page.locator('[data-nav="checklists"]').first().click();await page.locator('[data-check="0"]').check();await page.reload();assert(await page.locator('[data-check="0"]').isChecked());pass('Checklist state persists across reload');
 page.once('dialog',d=>d.accept());await page.locator('#reset-checklist').click();assert(!(await page.locator('[data-check="0"]').isChecked()));pass('Checklist reset');
 await page.locator('[data-nav="notes"]').first().click();await page.locator('[data-note="model"]').fill('TEST DEVICE — no customer data');await page.locator('[data-note="diagnosis"]').fill('<script>not executable</script> Test diagnosis');await page.reload();assert.equal(await page.locator('[data-note="model"]').inputValue(),'TEST DEVICE — no customer data');pass('Notes persist and render untrusted text safely');
 const [download]=await Promise.all([page.waitForEvent('download'),page.locator('#export-notes').click()]);await download.saveAs(path.join(out,'test-notes-export.txt'));assert(fs.readFileSync(path.join(out,'test-notes-export.txt'),'utf8').includes('TEST DEVICE'));pass('Notes export produces a real text download');
 await page.locator('[data-nav="settings"]').first().click();const [backup]=await Promise.all([page.waitForEvent('download'),page.locator('#export-state').click()]);const backupPath=path.join(out,'test-workspace-export.json');await backup.saveAs(backupPath);assert.equal(JSON.parse(fs.readFileSync(backupPath)).schemaVersion,1);pass('Workspace export includes a supported backup schema');
 await page.locator('[data-nav="notes"]').first().click();await page.locator('[data-note="model"]').fill('CHANGED');await page.locator('[data-nav="settings"]').first().click();page.once('dialog',d=>d.accept());await page.locator('#import-state').setInputFiles(backupPath);await page.waitForFunction(()=>document.querySelector('#toast').textContent.includes('imported'));await page.locator('[data-nav="notes"]').first().click();assert.equal(await page.locator('[data-note="model"]').inputValue(),'TEST DEVICE — no customer data');pass('Workspace import restores notes');
 await page.locator('[data-nav="tasks"]').first().click();await page.locator('[data-task="failing"]').click();assert((await page.locator('dialog').innerText()).includes('Image the failing disk'));await page.locator('[data-open-checklist="failing"]').click();assert((await page.locator('.panel h2').innerText()).includes('Failing Disk'));pass('Task guide links to its safety warning and checklist');
 await page.locator('#search').fill('diskpart');await page.locator('[data-detail="diskpart"]').first().click();assert((await page.locator('#detail-body').innerText()).includes('HIGH RISK'));assert.equal(await page.locator('#detail-body pre').innerText(),'diskpart\nlist disk\nlist volume\nexit');await page.keyboard.press('Escape');assert(!(await page.locator('dialog').isVisible()));pass('Destructive utility details have prominent risk and safe command template');
 await page.locator('#search').fill('CrystalDiskInfo');await page.locator('[data-detail="cdi"]').first().click();assert(await page.locator('#detail-body button:disabled').count());const folder=await page.locator('#detail-body a').filter({hasText:'OPEN FOLDER'}).getAttribute('href');assert(folder.startsWith('file:')&&folder.includes('/20_PORTABLE_APPS/'));pass('Missing binaries cannot be opened; folder links resolve to full file URLs');await page.keyboard.press('Escape');
 await page.locator('[data-nav="downloads"]').first().click();assert(await page.locator('tbody tr').count()>0);assert(await page.locator('tbody tr').evaluateAll(rows=>rows.every(r=>r.textContent.includes('P1')||r.textContent.includes('P2'))));pass('Missing Downloads contains only missing P1/P2 packages');
 await page.locator('[data-nav="updates"]').first().click();assert((await page.locator('main').innerText()).includes('DOWNLOAD FRESH COPY'));pass('Updates supports stale-scanner warnings');
 await page.locator('[data-nav="storage"]').first().click();assert((await page.locator('main').innerText()).includes('20–30 GB'));pass('Storage budget includes free-space reserve');
 await page.locator('[data-nav="home"]').first().click();await page.locator('#theme').click();await page.reload();assert.equal(await page.locator('html').getAttribute('data-theme'),'light');await page.screenshot({path:path.join(out,'overview-light-1440.png'),fullPage:true});pass('Light theme persists');await page.locator('#theme').click();
 for(const [width,height] of [[1366,768],[1024,768],[768,1024],[390,844]]){await page.setViewportSize({width,height});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await page.screenshot({path:path.join(out,`overview-${width}.png`),fullPage:true})}pass('No horizontal overflow at laptop, tablet and mobile widths');
 await page.setViewportSize({width:1366,height:768});await page.locator('body').click({position:{x:500,y:200}});await page.keyboard.press('/');assert.equal(await page.evaluate(()=>document.activeElement.id),'search');await page.locator('#search').fill('nonsense-test-no-match');assert((await page.locator('.empty').innerText()).includes('No matching'));await page.keyboard.press('Escape');assert.equal(await page.locator('#search').inputValue(),'');pass('Keyboard shortcuts and empty-result recovery');
 await page.goto(pathToFileURL(path.join(root,'70_DOCUMENTATION/reference.html')).href+'#bios');await page.locator('#boot-search').fill('Surface');assert.equal(await page.locator('#boot-table tbody tr:visible').count(),1);pass('Offline BIOS reference is searchable');
 const fixture=path.join(root,'.validation-no-inventory.html');fs.writeFileSync(fixture,fs.readFileSync(path.join(root,'index.html'),'utf8').replace('src="assets/js/local-inventory.js"','src="assets/js/not-present-inventory.js"'));
 try{await page.goto(pathToFileURL(fixture).href);await page.waitForSelector('h1');await page.locator('[data-nav="tools"]').first().click();await page.locator('#installed-filter').click();assert.equal(await page.locator('.tool-card').count(),0);pass('Missing inventory file gracefully degrades to unscanned state')}finally{fs.unlinkSync(fixture)}
 const blocked=await browser.newContext({viewport:{width:1366,height:768}});await blocked.setOffline(true);await blocked.addInitScript(()=>{Object.defineProperty(window,'localStorage',{get(){throw new Error('Storage disabled')}})});const bp=await blocked.newPage();await bp.goto(url);assert((await bp.locator('main').innerText()).includes('Browser storage is unavailable'));await bp.locator('[data-nav="notes"]').first().click();await bp.locator('[data-note="model"]').fill('Volatile note');assert((await bp.locator('#notes-state').innerText()).includes('unavailable'));pass('Blocked localStorage remains usable with export warning');await blocked.close();
 assert.equal(network.length,0,'Unexpected web dependencies');assert.deepEqual(errors,[]);pass('No JavaScript page errors or HTTP requests during offline tests');
 await context.close();await browser.close();
 fs.writeFileSync(path.join(out,'browser-results.json'),JSON.stringify({testedAt:new Date().toISOString(),browser:'Microsoft Edge / Playwright',protocol:'file:',offline:true,results,errors,network},null,2));
 console.log(`${results.length} browser checks passed.`);
})().catch(e=>{fs.writeFileSync(path.join(out,'browser-failure.txt'),e.stack);console.error(e);process.exit(1)});
